      codigoInicial: "def nivel_didactico(uso):\n    return None\n\nfor uso in [\"puntuacion social\", \"credito\", \"empleo\", \"chatbot\", \"contenido generado\", \"recomendar peliculas\"]:\n    print(uso, \"->\", nivel_didactico(uso))",
