      solucion: "from sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.metrics.pairwise import cosine_similarity\n\nFAQ = {\n    1: \"Los envíos nacionales tardan entre 2 y 5 días hábiles. Los envíos a Bogotá, Medellín y Cali llegan en 2 días hábiles. El envío es gratis en compras superiores a 150000 pesos.\",\n    2: \"Puedes devolver un producto dentro de los 30 días posteriores a la entrega si está sin usar y en su empaque original. El reembolso se procesa en 7 días hábiles.\",\n    3: \"Todos los productos tecnológicos tienen garantía de 12 meses por defectos de fábrica. La garantía no cubre daños por golpes ni por líquidos.\",\n    4: \"Aceptamos tarjetas de crédito, tarjetas débito, PSE y transferencia bancaria. El pago con tarjeta de crédito se puede diferir hasta en 12 cuotas.\",\n    5: \"La factura electrónica se envía al correo registrado dentro de las 24 horas siguientes a la compra. Para cambiar los datos de facturación escribe a soporte antes de 5 días.\",\n    6: \"El soporte atiende de lunes a viernes de 8 a.m. a 6 p.m. por chat y correo electrónico. Los sábados atendemos solo por chat hasta las 2 p.m.\",\n}\nPALABRAS_VACIAS = [\"de\", \"la\", \"el\", \"los\", \"las\", \"un\", \"una\", \"y\", \"a\", \"en\", \"por\", \"con\", \"para\", \"se\", \"es\", \"que\", \"del\", \"al\",\n                   \"lo\", \"su\", \"mi\", \"mis\", \"tu\", \"o\", \"me\", \"si\", \"no\", \"hay\", \"puedo\", \"puedes\", \"cual\", \"como\", \"cuanto\",\n                   \"cuantos\", \"tienen\", \"tiene\", \"son\", \"ni\", \"sin\", \"solo\", \"hasta\", \"entre\", \"antes\", \"dentro\", \"todos\",\n                   \"esta\", \"esto\", \"ese\", \"pueden\", \"cuales\", \"donde\", \"cuando\", \"venden\", \"atienden\"]\n\nclass Buscador:\n    \"\"\"Índice TF-IDF sobre las preguntas frecuentes (representación léxica, sin modelo de embeddings).\"\"\"\n    def __init__(self, documentos):\n        self.ids = list(documentos)\n        self.vec = TfidfVectorizer(strip_accents=\"unicode\", stop_words=PALABRAS_VACIAS)\n        self.matriz = self.vec.fit_transform([documentos[i] for i in self.ids])\n\n    def buscar(self, pregunta):\n        \"\"\"Devuelve (id, similitud) del documento más parecido.\"\"\"\n        similitudes = cosine_similarity(self.vec.transform([pregunta]), self.matriz)[0]\n        mejor = int(similitudes.argmax())\n        return self.ids[mejor], round(float(similitudes[mejor]), 2)\n\nimport json\nimport re\nimport unicodedata\n\nbuscador = Buscador(FAQ)\n\ndef anonimizar(texto):\n    texto = re.sub(r\"[\\w.+-]+@[\\w-]+\\.[\\w.]+\", \"[EMAIL]\", texto)\n    texto = re.sub(r\"\\b3\\d{9}\\b\", \"[TELEFONO]\", texto)\n    return texto\n\ndef prompt_con_reglas(contexto, pregunta):\n    return (\"Responde usando solo el contenido de <contexto>.\\n\"\n            \"Si la respuesta no está en el contexto, responde exactamente: No tengo esa información.\\n\"\n            \"\\n\"\n            f\"<contexto>\\n{contexto}\\n</contexto>\\n\"\n            \"\\n\"\n            f\"Pregunta: {pregunta}\")\n\ndef normalizar(texto):\n    sin_tildes = unicodedata.normalize(\"NFD\", texto.lower())\n    return re.findall(r\"[a-z0-9]+\", \"\".join(c for c in sin_tildes if unicodedata.category(c) != \"Mn\"))\n\ndef modelo_simulado(prompt):\n    \"\"\"Modelo simulado: devuelve en JSON la frase del contexto que más se parece a la pregunta y la fuente citada.\"\"\"\n    contexto = re.search(r\"<contexto>\\n(.*?)\\n</contexto>\", prompt, re.DOTALL).group(1)\n    pregunta = re.search(r\"Pregunta: (.*)\", prompt).group(1)\n    fuente = int(re.search(r\"\\[doc:(\\d+)\\]\", contexto).group(1))\n    texto = re.sub(r\"^\\[doc:\\d+\\]\\s*\", \"\", contexto)\n    frases = re.split(r\"(?<=\\.)\\s+(?=[A-ZÁÉÍÓÚ])\", texto)\n    clave = {p for p in normalizar(pregunta) if p not in PALABRAS_VACIAS}\n    mejor = max(frases, key=lambda f: len(clave & set(normalizar(f))))   # en empate, la primera\n    return json.dumps({\"respuesta\": mejor, \"fuente\": fuente}, ensure_ascii=False)\n\ndef procesar(pregunta, umbral=0.25):\n    limpia = anonimizar(pregunta)\n    doc_id, similitud = buscador.buscar(limpia)\n    if similitud < umbral:\n        return \"No tengo esa información\"\n    contexto = f\"[doc:{doc_id}] {FAQ[doc_id]}\"\n    salida = json.loads(modelo_simulado(prompt_con_reglas(contexto, limpia)))\n    if salida[\"fuente\"] not in FAQ:\n        return \"No tengo esa información\"\n    return f\"{salida['respuesta']} [doc {salida['fuente']}]\"\n\nfor p in [\"¿Atienden los sábados? Soy ana@mail.com\", \"¿Puedo devolver un producto?\", \"¿Cuál es la capital de Francia?\"]:\n    print(procesar(p))",
